def svg(name: str, size: int = 24, cls: str = "", stroke: float = 1.9) -> str:
    """An inline, decorative SVG icon. Unknown names raise KeyError (caught by tests)."""
    return ('<svg class="ss-ic%s" xmlns="http://www.w3.org/2000/svg" width="%d" height="%d" viewBox="0 0 24 24" fill="none" '
            'stroke="currentColor" stroke-width="%s" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" '
            'focusable="false">%s</svg>') % ((" " + cls) if cls else "", size, size, stroke, ICONS[name])


